/**
 * Synthetic `mp4s` containers for tests.
 *
 * The layout mirrors the validated container documented in
 * `spikes/001-remux-mp4s/README.md`:
 *
 *   header: "mp4s"@0 | u16 durationSec@8 | u32 audioFrames@10 | u16 asc@18 |
 *           u16 sampleRate@25 | u32 videoFrames@27 | u32 avcCSize@31 | avcC@35 |
 *           u16 width | u16 height
 *   index:  repeated [ u8: (sizeLen << 4) | type ][ sizeLen-byte big-endian size ]
 *   data:   packets in index order, each = 1-byte flags + payload
 *
 * The generated bytes are a valid container accepted by `parseMp4s`; the video
 * payloads are valid AVCC samples (4-byte big-endian NAL lengths) so they can be
 * copied into an MP4 unchanged.
 */

const SR_INDEX: Record<number, number> = {
  96000: 0,
  88200: 1,
  64000: 2,
  48000: 3,
  44100: 4,
  32000: 5,
  24000: 6,
  22050: 7,
  16000: 8,
  12000: 9,
  11025: 10,
  8000: 11,
  7350: 12,
}

/** A realistic AVCDecoderConfigurationRecord (H.264 High@4.0, one SPS + one PPS). */
export const DEFAULT_AVCC: Uint8Array = Uint8Array.from([
  0x01, 0x64, 0x00, 0x28, 0xff, 0xe1,
  0x00, 0x1a,
  0x67, 0x64, 0x00, 0x28, 0xac, 0xd9, 0x40, 0x78, 0x02, 0x27, 0xe5, 0x84, 0x00, 0x00, 0x03,
  0x00, 0x04, 0x00, 0x00, 0x03, 0x00, 0xc8, 0x3c, 0x60, 0xc6, 0x58,
  0x01, 0x00, 0x06,
  0x68, 0xeb, 0xe3, 0xcb, 0x22, 0xc0,
])

export interface Mp4sFixtureOptions {
  videoFrames?: number
  audioFrames?: number
  width?: number
  height?: number
  sampleRate?: number
  channels?: number
  avcC?: Uint8Array
  durationSec?: number
  /** Value written into every packet's flags byte. The parser must not require 0. */
  flags?: number
  /**
   * Minimum NAL payload length for video samples. Used by tests that need a
   * container larger than one CDN segment (2 MiB).
   */
  videoSampleSize?: number
}

function writeU16(value: number): Uint8Array {
  const bytes = new Uint8Array(2)
  new DataView(bytes.buffer).setUint16(0, value)
  return bytes
}

function writeU32(value: number): Uint8Array {
  const bytes = new Uint8Array(4)
  new DataView(bytes.buffer).setUint32(0, value)
  return bytes
}

function ascii(text: string): Uint8Array {
  const bytes = new Uint8Array(text.length)
  for (let i = 0; i < text.length; i++) bytes[i] = text.charCodeAt(i) & 0xff
  return bytes
}

function concat(parts: readonly Uint8Array[]): Uint8Array {
  let total = 0
  for (const part of parts) total += part.length
  const out = new Uint8Array(total)
  let offset = 0
  for (const part of parts) {
    out.set(part, offset)
    offset += part.length
  }
  return out
}

/** Big-endian size encoded in the smallest number of bytes (1..4). */
function encodeSize(size: number): Uint8Array {
  const length = size <= 0xff ? 1 : size <= 0xffff ? 2 : size <= 0xffffff ? 3 : 4
  const out = new Uint8Array(length)
  let value = size
  for (let i = length - 1; i >= 0; i--) {
    out[i] = value & 0xff
    value = Math.floor(value / 256)
  }
  return out
}

interface Packet {
  type: number
  data: Uint8Array
}

function makeNal(header: number, index: number, length: number): Uint8Array {
  const nal = new Uint8Array(length)
  nal[0] = header
  for (let i = 1; i < length; i++) nal[i] = (index * 31 + i * 17 + 0x40) & 0xff
  return nal
}

/** A valid AVCC sample: one or more `[u32 length][NAL]` units. */
function makeVideoSample(index: number, keyframe: boolean, minSampleSize?: number): Uint8Array {
  const nals: Uint8Array[] = []
  if (keyframe) nals.push(makeNal(0x67, index, 8 + (index % 3)))
  const baseLength = 24 + ((index * 13) % 80)
  const length = minSampleSize !== undefined && minSampleSize > baseLength ? minSampleSize : baseLength
  nals.push(makeNal(keyframe ? 0x65 : 0x41, index, length))
  return concat(nals.map((nal) => concat([writeU32(nal.length), nal])))
}

function makeAudioSample(index: number): Uint8Array {
  // Varies across the 1- and 2-byte sizeLen ranges, like real AAC frames.
  const length = 40 + ((index * 53) % 400)
  const frame = new Uint8Array(length)
  for (let i = 0; i < length; i++) frame[i] = (index * 7 + i * 3) & 0xff
  return frame
}

/**
 * Builds a synthetic, structurally valid `mp4s` container.
 *
 * Video frames use `type 2` for keyframes (every third frame, starting at 0) and
 * `type 1` otherwise; audio frames use `type 0`. Index sizes are encoded with the
 * minimal `sizeLen`, and the index tiles the data region exactly.
 */
export function makeMp4s(options: Mp4sFixtureOptions = {}): Uint8Array {
  const videoFrames = options.videoFrames ?? 5
  const audioFrames = options.audioFrames ?? 12
  const width = options.width ?? 832
  const height = options.height ?? 470
  const sampleRate = options.sampleRate ?? 48000
  const channels = options.channels ?? 1
  const avcC = options.avcC ?? DEFAULT_AVCC
  const flags = options.flags ?? 0
  const durationSec = options.durationSec ?? Math.round((audioFrames * 1024) / sampleRate)

  const srIndex = SR_INDEX[sampleRate] ?? 3
  const ascVal = (2 << 11) | (srIndex << 7) | ((channels & 0x0f) << 3)

  const packets: Packet[] = []
  for (let i = 0; i < Math.max(videoFrames, audioFrames); i++) {
    if (i < videoFrames) {
      const isKeyframe = i === 0 || i % 3 === 0
      packets.push({
        type: isKeyframe ? 2 : 1,
        data: makeVideoSample(i, isKeyframe, options.videoSampleSize),
      })
    }
    if (i < audioFrames) packets.push({ type: 0, data: makeAudioSample(i) })
  }

  const header = concat([
    ascii('mp4s'),
    new Uint8Array(4),
    writeU16(durationSec),
    writeU32(audioFrames),
    new Uint8Array(4),
    writeU16(ascVal),
    new Uint8Array(5),
    writeU16(sampleRate),
    writeU32(videoFrames),
    writeU32(avcC.length),
    avcC,
    writeU16(width),
    writeU16(height),
  ])

  const indexParts: Uint8Array[] = []
  const dataParts: Uint8Array[] = []
  for (const packet of packets) {
    const size = 1 + packet.data.length // flags byte + payload
    const sizeBytes = encodeSize(size)
    indexParts.push(Uint8Array.of((sizeBytes.length << 4) | packet.type), sizeBytes)
    dataParts.push(Uint8Array.of(flags & 0xff), packet.data)
  }

  return concat([header, ...indexParts, ...dataParts])
}

/** Offset of the first index entry for a container with the given avcC length. */
export function mp4sIndexOffset(avcCLength: number = DEFAULT_AVCC.length): number {
  return 35 + avcCLength + 4
}

/** Absolute offsets (relative to the haystack) of every occurrence of `needle`. */
export function findBytes(haystack: Uint8Array, needle: Uint8Array): number[] {
  const hits: number[] = []
  outer: for (let i = 0; i <= haystack.length - needle.length; i++) {
    for (let j = 0; j < needle.length; j++) {
      if (haystack[i + j] !== needle[j]) continue outer
    }
    hits.push(i)
  }
  return hits
}

/** Splits an AVCC sample into its NAL units; throws if the framing is invalid. */
export function splitAvcc(sample: Uint8Array): Uint8Array[] {
  const nals: Uint8Array[] = []
  const view = new DataView(sample.buffer, sample.byteOffset, sample.byteLength)
  let offset = 0
  while (offset < sample.length) {
    if (offset + 4 > sample.length) throw new Error('truncated AVCC length prefix')
    const length = view.getUint32(offset)
    offset += 4
    if (length === 0 || offset + length > sample.length) throw new Error('truncated AVCC NAL')
    nals.push(sample.subarray(offset, offset + length))
    offset += length
  }
  return nals
}
